mapper.select:
SELECT EXISTS (
    SELECT 1 FROM application
    WHERE business_id = #{businessId}
    AND fair_id = #{fairId}
    AND status IN ('PENDING_REVIEW', 'PAYMENT_PENDING', 'CONFIRMED')
)

SELECT aps.booth_slot_id FROM application_slot aps JOIN application a ON a.application_id = aps.application_id WHERE aps.booth_slot_id IN
#{id}
AND a.status IN ('PENDING_REVIEW', 'PAYMENT_PENDING', 'CONFIRMED') FOR UPDATE

SELECT a.application_id AS applicationId, f.name AS fairName, a.status AS status, a.final_price AS finalPrice, a.reject_reason AS rejectReason FROM application a JOIN business b ON b.business_id = a.business_id JOIN fairs f ON f.fair_id = a.fair_id WHERE b.owner_id = #{ownerId}
AND a.business_id = #{businessId}
ORDER BY a.submitted_at DESC
